// Database tab: recommendations inbox, top causes / groups / all, detail sheet, effect chart.
// Generated by aurora@aurora-smart-home (ha-integration-dev skill)
// https://github.com/tonylofgren/aurora-smart-home
import { html, nothing, svg } from "lit";
import { live } from "lit/directives/live.js";
import { bytes, number, percent, relativeTime, dateTime } from "./format.js";

export const TIER_ORDER = ["default", "7", "3", "1", "drop", "excluded"];
export const TIER_DAYS = { "7": 7, "3": 3, "1": 1, drop: 0, excluded: 0 };
const ENGINES = { sqlite: "SQLite", mysql: "MariaDB/MySQL", postgresql: "PostgreSQL" };
const PAGE = 150;

/** "every 2 s" / "every 5 min" / "12× per day" from rows in the last 24 h. */
export function rate(rows24h, t, lang) {
  if (!rows24h) return "–";
  const interval = 86400 / rows24h;
  if (interval < 60) return t("rate_seconds", { n: Math.max(1, Math.round(interval)) });
  if (interval < 3600) return t("rate_minutes", { n: Math.round(interval / 60) });
  return t("rate_per_day", { n: number(rows24h, lang) });
}

export const DatabaseSection = (Base) =>
  class extends Base {
    // ------------------------------------------------------------ helpers

    _tierLabel(tier) {
      const t = this.t;
      const keep = this._entities?.keep_days ?? this._overview?.data?.database?.keep_days;
      if (tier === "default") return t("tier_default", { days: keep });
      if (tier === "excluded")
        return this._entities?.packages_available === false ? t("tier_excluded_needs_packages") : t("tier_excluded");
      return t(`tier_${tier}`);
    }

    _reasonText(advice, row) {
      const t = this.t;
      if (!advice) return "";
      const used = advice.used || {};
      const vars = {
        rate: rate(row?.rows_24h, t, this.lang),
        share: percent(advice.facts?.attr_share || 0, this.lang),
        attr_only: percent(advice.facts?.attr_only_share || 0, this.lang),
        days: used.min_days || "",
      };
      return t(`reason_${advice.reason}`, vars);
    }

    _noteChips(advice) {
      const t = this.t;
      if (!advice) return nothing;
      const used = advice.used || {};
      const chips = [];
      if (advice.protected) chips.push(html`<span class="tag ok">${t(`protected_${advice.protected}`)}</span>`);
      if (used.automations || used.scripts)
        chips.push(html`<span class="tag" title=${t("note_automation_hint")}>${t("note_automation", { n: used.automations + used.scripts })}</span>`);
      if (used.min_days) chips.push(html`<span class="tag">${t("note_dashboard", { days: used.min_days })}</span>`);
      if (used.energy) chips.push(html`<span class="tag">${t("note_energy")}</span>`);
      if (advice.facts?.state_class) chips.push(html`<span class="tag" title=${t("note_statistics_hint")}>${t("note_statistics")}</span>`);
      if (advice.facts?.entity_category === "diagnostic") chips.push(html`<span class="tag">${t("note_diagnostic")}</span>`);
      return chips;
    }

    _integrationName(key) {
      const name = this.hass?.localize?.(`component.${key}.title`);
      return name || key.replace(/_/g, " ").replace(/^\w/, (c) => c.toUpperCase());
    }

    _rowById(entityId) {
      return this._entities?.rows.find((r) => r.entity_id === entityId);
    }

    _accept(entityIds) {
      const draft = new Map(this._draft);
      for (const id of entityIds) {
        const row = this._rowById(id);
        const action = row?.advice?.action;
        if (!row || !action || row.excluded_by_yaml) continue;
        if (action === this._original(row)) draft.delete(id);
        else draft.set(id, { value: action, row });
      }
      this._draft = draft;
    }

    async _dismiss(entityIds, undo = false) {
      try {
        await this._ws("dismiss", { entity_ids: entityIds, undo });
        await this._loadEntities();
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    async _openDetail(entityId) {
      this._detail = { entity_id: entityId, loading: true };
      try {
        this._detail = await this._ws("entity_detail", { entity_id: entityId });
      } catch (err) {
        this._detail = undefined;
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    // ------------------------------------------------------------- render

    _renderDatabase() {
      const t = this.t;
      const ov = this._overview;
      const db = ov.data.database;
      const rec = ov.data.recorder;
      const ent = this._entities;
      const running = db.analysis_running || this._working === "analyze";
      return html`
        ${rec.restart_required
          ? html`<div class="banner"><ha-icon icon="mdi:restart-alert"></ha-icon>
              <div class="txt">${t("restart_banner", { n: rec.pending_restart.length })}</div>
              <button class="btn primary" @click=${this._confirmRestart}>${t("restart")}</button></div>`
          : nothing}
        ${rec.unwritten.length && !rec.packages.available
          ? html`<div class="banner"><ha-icon icon="mdi:package-variant"></ha-icon>
              <div class="txt">${t("packages_banner")}</div>
              <button class="btn" @click=${() => this._navigate("/config/repairs")}>${t("packages_open")}</button></div>`
          : nothing}
        ${rec.core_entity_options === "writable"
          ? html`<div class="banner info"><ha-icon icon="mdi:new-box"></ha-icon>
              <div class="txt">${t("core_options_banner")}</div></div>`
          : nothing}
        ${ov.gui_recorder && !ov.gui_recorder_imported
          ? html`<div class="banner info"><ha-icon icon="mdi:import"></ha-icon>
              <div class="txt">${t("gui_recorder_banner")}</div>
              <button class="btn" @click=${this._importGuiRecorder}>${t("gui_recorder_import")}</button></div>`
          : nothing}

        <div class="grid2">
          <div class="card">
            <div class="kpis">
              <div class="kpi"><div class="v">${bytes(db.size, this.lang)}</div><div class="l">${t("db_size")}</div></div>
              <div class="kpi"><div class="v">${ENGINES[db.dialect] || db.dialect || "–"}</div><div class="l">${t("db_engine")}</div></div>
              <div class="kpi"><div class="v">${t("days", { n: db.keep_days })}</div><div class="l">${t("db_keep")}</div></div>
              <div class="kpi"><div class="v">${running ? html`<span class="spinner" style="width:18px;height:18px"></span>` : relativeTime(db.analysis_at, t, this.lang)}</div>
                <div class="l">${t("db_analysis")}</div></div>
            </div>
            ${db.obsolete?.states || db.obsolete?.events
              ? html`<div class="row obsolete">
                  <span class="small">${t("obsolete", {
                    n: number((db.obsolete.states || 0) + (db.obsolete.events || 0), this.lang),
                    bytes: bytes(db.obsolete.bytes, this.lang),
                    days: db.obsolete.keep_days,
                  })}</span>
                  <span class="spacer"></span>
                  <button class="btn" ?disabled=${!!this._working} @click=${() => this._previewAndClean(["purge"])}>${t("obsolete_purge")}</button>
                </div>`
              : nothing}
            <div class="row" style="margin-top:12px">
              <span class="muted small">${ent?.estimated_sizes === false ? t("db_calibrated") : ent?.dialect === "mysql" && ent?.calibrated ? t("db_estimated_innodb") : ent?.scaled_to_file ? t("db_scaled") : t("db_estimated")}
                ${rec.yaml_filters?.uses_include ? html` <b>${t("yaml_include_warning")}</b>` : nothing}</span>
              <span class="spacer"></span>
              <button class="btn" ?disabled=${running || !!this._working} @click=${this._analyze}>${t("analyze")}</button>
            </div>
            ${this._renderAnalysisProgress(db)}
          </div>
          ${this._renderEffect(ent)}
        </div>

        ${!ent
          ? html`<div class="card"><div class="center"><span class="spinner"></span></div></div>`
          : !ent.analysis_at
          ? html`<div class="card"><p class="muted">${t("analysis_needed")}</p></div>`
          : html`${this._renderInbox(ent)} ${this._renderExplorer(ent)}`}

        ${this._healthCard("database")}
        ${ent?.events?.length
          ? html`<div class="card"><h2>${t("events_title")}</h2>
              ${ent.events.slice(0, 8).map((e) => html`<div class="list-row"><div><code>${e.event_type}</code></div><div></div><div class="num">${number(e.rows, this.lang)}</div></div>`)}</div>`
          : nothing}
        ${this._renderDetail()}
      `;
    }

    // -------------------------------------------------------------- inbox

    _renderInbox(ent) {
      const t = this.t;
      const items = ent.inbox || [];
      const ids = (a) => a.entity_ids || [a.entity_id];
      const pending = items.flatMap(ids).filter((id) => !this._draft.has(id));
      return html`<div class="card">
        <h2>${t("inbox_title")}
          <span class="spacer"></span>
          ${items.length ? html`<span class="muted small">${t("inbox_summary", { n: items.length, bytes: bytes(ent.inbox_saving, this.lang) })}</span>` : nothing}
        </h2>
        ${items.length === 0
          ? html`<p class="muted">${t("inbox_empty")}</p>`
          : html`
              <p class="muted small" style="margin-top:-4px">${t("inbox_hint")}
                <button class="linklike" @click=${() => this._setTab("settings")}>${t("kinds_link")}</button></p>
              ${items.map((a) => this._renderInboxItem(a))}
              <div class="row" style="margin-top:12px">
                ${ent.dismissed_count
                  ? html`<button class="btn" @click=${() => this._dismiss([], true)}>${t("inbox_show_dismissed", { n: ent.dismissed_count })}</button>`
                  : nothing}
                <span class="spacer"></span>
                <button class="btn primary" ?disabled=${!pending.length}
                  @click=${() => this._accept(pending)}>${t("inbox_accept_all", { n: pending.length })}</button>
              </div>`}
        ${!items.length && ent.dismissed_count
          ? html`<button class="btn" @click=${() => this._dismiss([], true)}>${t("inbox_show_dismissed", { n: ent.dismissed_count })}</button>`
          : nothing}
      </div>`;
    }

    // ------------------------------------------------------- kinds of sensor

    _renderKinds(ent) {
      const t = this.t;
      if (!ent) return html`<div class="card"><h2>${t("kinds_title")}</h2><div class="center"><span class="spinner"></span></div></div>`;
      const kinds = ent.kinds || [];
      const changed = kinds.filter((k) => k.value).length;
      return html`<div class="card">
        <h2>${t("kinds_title")}
          <span class="spacer"></span>
          ${changed ? html`<span class="tag">${t("kinds_changed", { n: changed })}</span>` : nothing}
        </h2>
        <p class="muted small" style="margin-top:0">${t("kinds_hint")}</p>
        <p class="muted small">${t("kinds_auto_hint")}</p>
        ${kinds.length ? kinds.map((k) => this._renderKind(k)) : html`<p class="muted">${t("analysis_needed")}</p>`}
      </div>`;
    }

    _renderSettingsTab() {
      const t = this.t;
      const ent = this._entities;
      return html`
        ${this._renderKinds(ent)}
        ${this._renderSettings(ent)}
        <div class="card">
          <h2>${t("more_options_title")}</h2>
          <p class="muted small" style="margin-top:0">${t("more_options_hint")}</p>
          <button class="btn" @click=${() => this._navigate("/config/integrations/integration/storage_manager")}>${t("options")}</button>
        </div>`;
    }

    _renderKind(k) {
      const t = this.t;
      const values = ["7", "3", "1", "drop", ...(k.statistics_only ? [] : ["excluded"]), "off"];
      const label = (v) => (v === "off" ? t("kind_off") : this._tierLabel(v));
      return html`<div class="list-row kind-row">
        <div>
          <div>${t(`kind_${k.kind}`)}</div>
          <div class="muted small">${t(`kind_${k.kind}_desc`)}</div>
          <div class="muted small">${k.entities
            ? t(k.saving ? "kind_stats" : "kind_stats_nosave", { n: number(k.entities, this.lang), bytes: bytes(k.bytes, this.lang), saving: bytes(k.saving, this.lang) })
            : t("kind_none")}</div>
          <label class="small kind-auto">
            <input type="checkbox" .checked=${!!k.auto && k.value !== "off"}
              ?disabled=${!!this._working || k.value === "off"}
              @change=${(e) => this._setKindAuto(k.kind, e.target.checked)} />
            ${k.auto && k.value !== "off"
              ? t("kind_auto_since", { date: dateTime(k.auto, this.lang) })
              : t("kind_auto")}
          </label>
        </div>
        <div></div>
        <div>
          <select aria-label=${t(`kind_${k.kind}`)} ?disabled=${!!this._working}
            @change=${(e) => this._setKind(k.kind, e.target.value || null)}>
            <option value="" ?selected=${!k.value}>${t("kind_default", { tier: label(k.default) })}</option>
            ${values.map((v) => html`<option value=${v} ?selected=${k.value === v}>${label(v)}</option>`)}
          </select>
        </div>
      </div>`;
    }

    _setKind(kind, value) {
      return this._sendKinds({ rules: { [kind]: value } });
    }

    _setKindAuto(kind, enabled) {
      return this._sendKinds({ auto: { [kind]: enabled } });
    }

    async _sendKinds(payload) {
      this._working = "kinds";
      try {
        await this._ws("kind_rules", payload);
        await Promise.all([this._loadEntities(), this._loadOverview()]);
        this._showToast(this.t("kinds_saved"));
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      } finally {
        this._working = null;
      }
    }

    _toggleGroup(key) {
      const s = new Set(this._openGroups || []);
      s.has(key) ? s.delete(key) : s.add(key);
      this._openGroups = s;
    }

    _renderInboxItem(a) {
      const t = this.t;
      const row = this._rowById(a.entity_id);
      const ids = a.entity_ids || [a.entity_id];
      const inDraft = ids.every((id) => this._draft.get(id)?.value === a.action);
      const open = this._openGroups?.has(`inbox:${a.group}`);
      const title = a.entity_ids
        ? html`<button class="linklike t" @click=${() => this._toggleGroup(`inbox:${a.group}`)}>
            ${t("inbox_group_title", { integration: this._integrationName(a.integration), n: a.count })}</button>`
        : html`<button class="linklike t" @click=${() => this._openDetail(a.entity_id)}>${a.name}</button>`;
      return html`<div class="rec ${a.conflict ? "conflict" : ""}">
        <div class="ico"><ha-icon icon=${a.conflict ? "mdi:alert-outline" : a.entity_ids ? "mdi:format-list-group" : "mdi:lightbulb-on-outline"}></ha-icon></div>
        <div>
          ${title}
          <div class="muted small">${a.entity_ids ? t(`group_reason_${a.reason}`, { n: a.count }) : this._reasonText(a, row)}</div>
          ${a.hint ? html`<div class="small hint">${t(`hint_${a.hint}`)}</div>` : nothing}
          <div class="chips">
            <span class="tag ${a.conflict ? "warn" : "ok"}">→ ${this._tierLabel(a.action)}</span>
            ${this._noteChips({ ...a, protected: null })}
          </div>
          ${a.entity_ids && open
            ? html`<ul class="group-members">${a.entity_ids.map((id) => html`<li><button class="linklike" @click=${() => this._openDetail(id)}>${this._rowById(id)?.name || id}</button></li>`)}</ul>`
            : nothing}
        </div>
        <div class="act row">
          ${a.saving ? html`<span class="amount">${bytes(a.saving, this.lang)}</span>` : nothing}
          ${inDraft
            ? html`<span class="tag ok">${t("inbox_in_draft")}</span>`
            : html`<button class="btn" @click=${() => this._dismiss(ids)}>${t("inbox_dismiss")}</button>
                <button class="btn primary" @click=${() => this._accept(ids)}>${t("inbox_accept")}</button>`}
        </div>
      </div>`;
    }

    // ------------------------------------------------------------- effect

    _renderEffect(ent) {
      const t = this.t;
      const samples = (ent?.size_history || []).filter((s) => s[2] > 0);
      const changes = (ent?.changes || []).map((c) => new Date(c).getTime() / 1000);
      let summary = t("effect_waiting");
      if (samples.length >= 2 && changes.length) {
        const first = changes[0];
        const before = [...samples].reverse().find((s) => s[0] <= first) || samples[0];
        const latest = samples[samples.length - 1];
        if (latest[0] > before[0]) {
          const delta = (latest[2] - before[2]) / before[2];
          summary = t("effect_since_change", {
            delta: `${delta <= 0 ? "−" : "+"}${percent(Math.abs(delta), this.lang)}`,
            bytes: bytes(Math.abs(latest[2] - before[2]), this.lang),
          });
        }
      } else if (samples.length >= 2) {
        summary = t("effect_no_changes");
      }
      return html`<div class="card">
        <h2>${t("effect_title")}</h2>
        ${samples.length >= 2 ? this._sizeChart(samples, changes) : html`<p class="muted small">${t("effect_need_samples")}</p>`}
        <p class="small" style="margin:8px 0 0">${summary}</p>
      </div>`;
    }

    _sizeChart(samples, changes) {
      const w = 320;
      const h = 90;
      const xs = samples.map((s) => s[0]);
      const ys = samples.map((s) => s[2]);
      const x0 = Math.min(...xs);
      const x1 = Math.max(...xs, x0 + 1);
      const y1 = Math.max(...ys) * 1.05;
      const sx = (x) => ((x - x0) / (x1 - x0)) * w;
      const sy = (y) => h - (y / y1) * h;
      const line = samples.map((s, i) => `${i ? "L" : "M"}${sx(s[0]).toFixed(1)},${sy(s[2]).toFixed(1)}`).join(" ");
      const area = `${line} L${sx(x1).toFixed(1)},${h} L0,${h} Z`;
      return html`<svg class="chart" viewBox="0 0 ${w} ${h + 14}" role="img" aria-label=${this.t("effect_title")}>
        ${svg`<path d=${area} fill="var(--sm-c1)" opacity="0.12"></path>
          <path d=${line} fill="none" stroke="var(--sm-c1)" stroke-width="2"></path>
          ${changes.filter((c) => c >= x0 && c <= x1).map((c) => svg`<line x1=${sx(c)} x2=${sx(c)} y1="0" y2=${h} stroke="var(--warning-color, #ffa600)" stroke-dasharray="3 3"></line>`)}
          <text x="0" y=${h + 12} font-size="10" fill="var(--secondary-text-color)">${dateTime(x0, this.lang)}</text>
          <text x=${w} y=${h + 12} font-size="10" text-anchor="end" fill="var(--secondary-text-color)">${bytes(ys[ys.length - 1], this.lang)}</text>`}
      </svg>`;
    }

    // ----------------------------------------------------------- explorer

    _renderExplorer(ent) {
      const t = this.t;
      const view = this._view || "top";
      return html`<div class="card">
        <div class="row" style="margin-bottom:12px">
          <div class="segmented" role="tablist">
            ${["top", "groups", "all"].map(
              (v) => html`<button role="tab" aria-selected=${v === view ? "true" : "false"}
                @click=${() => { this._view = v; this._limit = PAGE; }}>${t(`view_${v}`)}</button>`
            )}
          </div>
          <span class="spacer"></span>
          <span class="muted small">${t("view_total", { n: number(ent.rows.length, this.lang), bytes: bytes(ent.total_bytes, this.lang) })}</span>
        </div>
        ${view === "groups" ? this._renderGroups(ent) : view === "all" ? this._renderAll(ent) : this._renderTop(ent)}
      </div>`;
    }

    _renderTop(ent) {
      const t = this.t;
      const rows = ent.rows.filter((r) => r.top || this._draft.has(r.entity_id));
      const max = rows.reduce((m, r) => Math.max(m, r.est_bytes), 1);
      const share = ent.total_bytes ? 1 - ent.rest_bytes / ent.total_bytes : 0;
      return html`
        <p class="muted small" style="margin-top:0">${t("top_hint", { n: rows.length, share: percent(share, this.lang) })}</p>
        ${this._table(rows, max)}
        ${ent.rest_count
          ? html`<div class="restline">
              <span>${t("top_rest", { n: number(ent.rest_count, this.lang), bytes: bytes(ent.rest_bytes, this.lang), share: percent(ent.total_bytes ? ent.rest_bytes / ent.total_bytes : 0, this.lang) })}</span>
              <button class="btn" @click=${() => (this._view = "all")}>${t("top_show_all")}</button>
            </div>`
          : nothing}`;
    }

    _groups(ent) {
      const groups = new Map();
      for (const r of ent.rows) {
        const key = r.integration || r.domain;
        if (!groups.has(key)) groups.set(key, { key, rows: [], bytes: 0, advice: [], saving: 0 });
        const g = groups.get(key);
        g.rows.push(r);
        g.bytes += r.est_bytes;
        if (r.advice?.action) {
          g.advice.push(r.entity_id);
          g.saving += r.advice.saving || 0;
        }
      }
      return [...groups.values()].sort((a, b) => b.bytes - a.bytes);
    }

    _renderGroups(ent) {
      const t = this.t;
      const groups = this._groups(ent);
      const open = this._openGroups || new Set();
      const total = ent.total_bytes || 1;
      return html`${groups.map((g) => {
        const isOpen = open.has(g.key);
        const max = g.rows.reduce((m, r) => Math.max(m, r.est_bytes), 1);
        return html`<div class="group">
          <div class="group-head">
            <button class="linklike group-toggle" aria-expanded=${isOpen ? "true" : "false"} @click=${() => {
              const s = new Set(open);
              isOpen ? s.delete(g.key) : s.add(g.key);
              this._openGroups = s;
            }}>
              <span class="chev">${isOpen ? "▾" : "▸"}</span>
              <span><b>${this._integrationName(g.key)}</b> <span class="muted small">${t("group_count", { n: g.rows.length })}</span></span>
            </button>
            <span class="spacer"></span>
            ${g.advice.length
              ? html`<button class="btn" @click=${() => this._accept(g.advice)}>${t("group_accept", { n: g.advice.length, bytes: bytes(g.saving, this.lang) })}</button>`
              : nothing}
            <span class="num"><b>${bytes(g.bytes, this.lang)}</b></span>
          </div>
          <div class="bar"><div style="width:${Math.max((g.bytes / total) * 100, 0.5)}%;background:var(--sm-c1)"></div></div>
          ${isOpen ? this._table(g.rows.slice(0, PAGE), max) : nothing}
        </div>`;
      })}`;
    }

    _filteredRows(rows) {
      const q = (this._search || "").trim().toLowerCase();
      let out = rows.filter((r) => {
        if (this._domain && r.domain !== this._domain) return false;
        if (this._onlyOrphans && !r.orphan) return false;
        if (this._onlyChanged && !this._draft.has(r.entity_id) && r.tier === "default" && !r.excluded) return false;
        if (this._onlyAdvice && !r.advice?.action) return false;
        if (!q) return true;
        return [r.entity_id, r.name, r.integration, r.area, r.device].some((v) => (v || "").toLowerCase().includes(q));
      });
      if (this._sort === "rate") out = [...out].sort((a, b) => b.rows_24h - a.rows_24h);
      else if (this._sort === "name") out = [...out].sort((a, b) => (a.name || "").localeCompare(b.name || "", this.lang));
      return out;
    }

    _renderAll(ent) {
      const t = this.t;
      const domains = [...new Set(ent.rows.map((r) => r.domain))].sort();
      const rows = this._filteredRows(ent.rows);
      const max = rows.reduce((m, r) => Math.max(m, r.est_bytes), 1);
      const shown = rows.slice(0, this._limit);
      return html`
        <div class="filters">
          <input type="search" placeholder=${t("search")} .value=${this._search}
            @input=${(e) => { this._search = e.target.value; this._limit = PAGE; }} />
          <select @change=${(e) => { this._domain = e.target.value; this._limit = PAGE; }} aria-label=${t("all_domains")}>
            <option value="">${t("all_domains")}</option>
            ${domains.map((d) => html`<option value=${d} ?selected=${d === this._domain}>${d}</option>`)}
          </select>
          <select @change=${(e) => (this._sort = e.target.value)} aria-label="sort">
            ${["size", "rate", "name"].map((s) => html`<option value=${s} ?selected=${s === this._sort}>${t(`sort_${s}`)}</option>`)}
          </select>
          <button class="chip" aria-pressed=${this._onlyAdvice ? "true" : "false"}
            @click=${() => (this._onlyAdvice = !this._onlyAdvice)}>${t("filter_advice")}</button>
          <button class="chip" aria-pressed=${this._onlyChanged ? "true" : "false"}
            @click=${() => (this._onlyChanged = !this._onlyChanged)}>${t("filter_changed")}</button>
          <button class="chip" aria-pressed=${this._onlyOrphans ? "true" : "false"}
            @click=${() => (this._onlyOrphans = !this._onlyOrphans)}>${t("filter_orphans")}</button>
        </div>
        ${this._selected.size
          ? html`<div class="banner info" style="margin-bottom:8px">
              <div class="txt">${t("selected", { n: this._selected.size })}</div>
              ${this._tierSelect(null, (v) => this._setValue(ent.rows.filter((r) => this._selected.has(r.entity_id)), v), t("set_for_selection"))}
              <button class="btn" @click=${() => (this._selected = new Set())}>${t("clear_selection")}</button>
            </div>`
          : nothing}
        ${this._table(shown, max, true)}
        ${rows.length > this._limit
          ? html`<div class="row" style="justify-content:center;margin-top:12px">
              <button class="btn" @click=${() => (this._limit += PAGE)}>${t("show_more", { n: Math.min(PAGE, rows.length - this._limit) })}</button></div>`
          : nothing}`;
    }

    _table(rows, max, selectable = false) {
      const t = this.t;
      const allSelected = selectable && rows.length > 0 && rows.every((r) => this._selected.has(r.entity_id));
      return html`<table class="responsive ${selectable ? "" : "noselect"}">
        <thead><tr>
          ${selectable
            ? html`<th style="width:28px"><input type="checkbox" .checked=${allSelected} aria-label="select all"
                @change=${(e) => {
                  const s = new Set(this._selected);
                  rows.forEach((r) => (e.target.checked ? s.add(r.entity_id) : s.delete(r.entity_id)));
                  this._selected = s;
                }} /></th>`
            : nothing}
          <th>${t("col_entity")}</th>
          <th class="num">${t("col_size")}</th>
          <th class="num">${t("col_rate")}</th>
          <th>${t("col_retention")}</th>
        </tr></thead>
        <tbody>${rows.map((r) => this._row(r, max, selectable))}</tbody>
      </table>`;
    }

    _row(r, max, selectable) {
      const t = this.t;
      const changed = this._draft.has(r.entity_id);
      const meta = [r.entity_id, r.integration, r.area].filter(Boolean).join(" · ");
      const advice = r.advice;
      const suggestion = advice?.action && this._effective(r) !== advice.action;
      return html`<tr class=${changed ? "changed" : ""}>
        ${selectable
          ? html`<td class="c-check"><input type="checkbox" .checked=${this._selected.has(r.entity_id)} aria-label=${r.entity_id}
              @change=${(e) => {
                const s = new Set(this._selected);
                e.target.checked ? s.add(r.entity_id) : s.delete(r.entity_id);
                this._selected = s;
              }} /></td>`
          : nothing}
        <td class="c-ent ent">
          <div class="n"><button class="linklike" @click=${() => this._openDetail(r.entity_id)}>${r.name}</button>
            ${r.orphan ? html`<span class="tag bad">${t("orphan")}</span>` : nothing}
            ${r.excluded_by_yaml ? html`<span class="tag">${t("excluded_by_yaml")}</span>` : nothing}
            ${r.excluded && !r.recorded ? html`<span class="tag ok">${t("tier_excluded")}</span>` : nothing}
          </div>
          <div class="i">${meta}</div>
          <div class="chips">
            ${suggestion
              ? html`<button class="tag ${advice.conflict ? "warn" : "ok"} tagbtn" title=${this._reasonText(advice, r)}
                  @click=${() => this._accept([r.entity_id])}>${advice.conflict ? "⚠ " : ""}${t("suggested", { tier: this._tierLabel(advice.action) })}</button>`
              : nothing}
            ${this._noteChips(advice)}
          </div>
        </td>
        <td class="c-size num">${r.est_bytes ? bytes(r.est_bytes, this.lang) : "–"}
          <div class="sizebar" style="width:${Math.max((r.est_bytes / max) * 100, 1)}%"></div></td>
        <td class="c-rate num">${rate(r.rows_24h, t, this.lang)}</td>
        <td class="c-tier">${this._tierSelect(r, (v) => this._setValue([r], v))}</td>
      </tr>`;
    }

    _tierSelect(row, onChange, placeholder) {
      const t = this.t;
      const value = row ? this._effective(row) : "";
      return html`<select aria-label=${t("col_retention")} ?disabled=${row?.excluded_by_yaml} .value=${live(value)}
        @change=${(e) => { onChange(e.target.value); if (!row) e.target.value = ""; }}>
        ${placeholder ? html`<option value="" selected disabled>${placeholder}</option>` : nothing}
        ${TIER_ORDER.map((tier) => html`<option value=${tier} ?selected=${tier === value}>${this._tierLabel(tier)}</option>`)}
      </select>`;
    }

    // ----------------------------------------------------------- settings

    _settingsState(rec) {
      if (!this._settingsDraft) {
        this._settingsDraft = {
          filters: JSON.parse(JSON.stringify(rec.filters || {})),
          settings: { ...(rec.settings || {}) },
        };
      }
      return this._settingsDraft;
    }

    _renderSettings(ent) {
      const t = this.t;
      const rec = this._overview.data.recorder;
      const orphans = rec.exclusion_orphans || { entities: [], domains: [], entity_globs: [] };
      const orphanCount = orphans.entities.length + orphans.domains.length + orphans.entity_globs.length;
      return html`<div class="card">
        <h2>${t("settings_title")}
          <span class="spacer"></span>
          ${orphanCount ? html`<span class="tag warn">${t("orphans_badge", { n: orphanCount })}</span>` : nothing}
        </h2>
        <p class="muted small" style="margin-top:0">${t("settings_hint")}</p>
        ${this._settingsBody(rec, ent, orphans, orphanCount)}
      </div>`;
    }

    _settingsBody(rec, ent, orphans, orphanCount) {
      const t = this.t;
      const st = this._settingsState(rec);
      const locked = rec.locked_settings || {};
      const eff = rec.effective_settings || {};
      const update = () => (this._settingsDraft = { ...st });
      const numberField = (key, min, max, unit) => {
        const isLocked = key in locked;
        const value = isLocked ? locked[key] : st.settings[key] ?? "";
        return html`<label class="field">
          <span>${t(`setting_${key}`)}</span>
          <span class="row">
            <input type="number" min=${min} max=${max} .value=${String(value)} placeholder=${String(eff[key] ?? "")}
              ?disabled=${isLocked}
              @change=${(e) => {
                const v = e.target.value === "" ? null : Number(e.target.value);
                st.settings = { ...st.settings, [key]: v };
                update();
              }} />
            <span class="muted small">${unit}</span>
          </span>
          <span class="muted small">${isLocked ? t("setting_locked") : t(`setting_${key}_hint`)}</span>
        </label>`;
      };
      const toggleField = (key) => {
        const isLocked = key in locked;
        const value = isLocked ? locked[key] : st.settings[key] ?? eff[key];
        return html`<label class="field toggle">
          <input type="checkbox" .checked=${!!value} ?disabled=${isLocked}
            @change=${(e) => { st.settings = { ...st.settings, [key]: e.target.checked }; update(); }} />
          <span><span>${t(`setting_${key}`)}</span><br />
            <span class="muted small">${isLocked ? t("setting_locked") : t(`setting_${key}_hint`)}</span></span>
        </label>`;
      };
      const domains = [...new Set((ent?.rows || []).map((r) => r.domain))].sort();
      const eventTypes = (ent?.events || []).map((e) => e.event_type);
      const listField = (key, suggestions) => {
        const values = st.filters[key] || [];
        const listId = `sm-${key}`;
        return html`<div class="field">
          <span>${t(`filter_${key}`)}</span>
          <div class="chips">
            ${values.map((v) => html`<span class="tag">${v}
              <button class="tagx" aria-label=${t("remove")} @click=${() => { st.filters = { ...st.filters, [key]: values.filter((x) => x !== v) }; update(); }}>✕</button></span>`)}
          </div>
          <span class="row">
            <input type="text" list=${listId} placeholder=${t(`filter_${key}_placeholder`)}
              @keydown=${(e) => {
                if (e.key !== "Enter" || !e.target.value.trim()) return;
                st.filters = { ...st.filters, [key]: [...new Set([...values, e.target.value.trim()])] };
                e.target.value = "";
                update();
              }} />
            <datalist id=${listId}>${suggestions.map((sug) => html`<option value=${sug}></option>`)}</datalist>
          </span>
          <span class="muted small">${t(`filter_${key}_hint`)}</span>
        </div>`;
      };
      return html`
        <p class="muted small" style="margin-top:0">${t("settings_restart_hint")}</p>
        <h4 class="sub">${t("settings_global")}</h4>
        <div class="fields">
          ${numberField("purge_keep_days", 1, 3650, t("unit_days"))}
          ${numberField("commit_interval", 0, 30, t("unit_seconds"))}
          ${toggleField("auto_purge")}
          ${toggleField("auto_repack")}
        </div>
        <h4 class="sub">${t("settings_filters")}</h4>
        <div class="fields">
          ${listField("domains", domains)}
          ${listField("entity_globs", [])}
          ${listField("event_types", eventTypes)}
        </div>
        ${orphanCount
          ? html`<div class="banner" style="margin-top:12px">
              <div class="txt">${t("orphans_text", { n: orphanCount })}
                <div class="muted small">${[...orphans.entities, ...orphans.domains, ...orphans.entity_globs].slice(0, 8).join(", ")}</div></div>
              <button class="btn" @click=${this._removeExclusionOrphans}>${t("orphans_remove")}</button>
            </div>`
          : nothing}
        <div class="row" style="margin-top:16px">
          <span class="spacer"></span>
          <button class="btn" @click=${() => (this._settingsDraft = undefined)}>${t("discard")}</button>
          <button class="btn primary" ?disabled=${!!this._working} @click=${this._saveSettings}>${t("settings_save")}</button>
        </div>`;
    }

    async _saveSettings() {
      const st = this._settingsDraft;
      if (!st) return;
      const locked = this._overview.data.recorder.locked_settings || {};
      const settings = Object.fromEntries(Object.entries(st.settings).filter(([k, v]) => !(k in locked) && v !== "" && v !== undefined));
      this._working = "settings";
      try {
        const res = await this._ws("settings", { filters: st.filters, settings });
        this._showToast(res.packages_missing ? this.t("packages_banner") : this.t("settings_saved"));
        this._settingsDraft = undefined;
        await Promise.all([this._loadOverview(), this._loadEntities()]);
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      } finally {
        this._working = null;
      }
    }

    async _removeExclusionOrphans() {
      try {
        const res = await this._ws("remove_exclusion_orphans");
        this._showToast(this.t("orphans_removed", { n: res.removed }));
        this._settingsDraft = undefined;
        await Promise.all([this._loadOverview(), this._loadEntities()]);
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    // ------------------------------------------------------------- detail

    _renderDetail() {
      const d = this._detail;
      if (!d) return nothing;
      const t = this.t;
      const close = () => (this._detail = undefined);
      const row = this._rowById(d.entity_id);
      const body = d.loading
        ? html`<div class="center"><span class="spinner"></span></div>`
        : this._detailBody(d, row);
      return html`<div class="scrim sheet-scrim" @click=${(e) => e.target === e.currentTarget && close()}
        @keydown=${(e) => e.key === "Escape" && close()}>
        <aside class="sheet" role="dialog" aria-modal="true" aria-label=${row?.name || d.entity_id}>
          <div class="sheet-head">
            <div>
              <h3>${row?.name || d.entity_id}</h3>
              <div class="muted small">${d.entity_id}</div>
            </div>
            <button class="icon-btn" aria-label=${t("cancel")} @click=${close}>✕</button>
          </div>
          ${body}
        </aside>
      </div>`;
    }

    _detailBody(d, row) {
      const t = this.t;
      const info = d.info || {};
      const advice = d.advice;
      const usage = d.usage || {};
      const maxDay = Math.max(...d.daily, 1);
      const value = row ? this._effective(row) : "default";
      const autoNames = (usage.automations || []).map((id) => this.hass.states[id]?.attributes?.friendly_name || id);
      const scriptNames = (usage.scripts || []).map((id) => this.hass.states[id]?.attributes?.friendly_name || id);
      return html`
        <div class="kpis" style="margin-bottom:16px">
          <div class="kpi"><div class="v">${bytes(info.est_bytes || 0, this.lang)}</div><div class="l">${t("col_size")}</div></div>
          <div class="kpi"><div class="v">${number(info.rows || 0, this.lang)}</div><div class="l">${t("col_rows")}</div></div>
          <div class="kpi"><div class="v">${rate(info.rows_24h, t, this.lang)}</div><div class="l">${t("detail_rate")}</div></div>
        </div>

        <h4>${t("detail_daily", { n: d.days })}</h4>
        <div class="spark" role="img" aria-label=${t("detail_daily", { n: d.days })}>
          ${d.daily.map((v, i) => html`<div title=${`${number(v, this.lang)}`} style="height:${Math.max((v / maxDay) * 100, v ? 3 : 0)}%"
            class=${i === d.daily.length - 1 ? "today" : ""}></div>`)}
        </div>

        ${d.sample_rows
          ? html`<p class="small">${t("detail_attr_only", {
              n: number(d.sample_attr_only, this.lang),
              total: number(d.sample_rows, this.lang),
            })}</p>`
          : nothing}
        ${(d.drivers || []).length
          ? html`<h4>${t("detail_drivers")}</h4>
              ${d.drivers.map(
                (a) => html`<div class="attr"><code>${a.name}</code>
                  ${a.driver ? html`<span class="tag warn">${t("detail_driver")}</span>` : nothing}
                  <span class="spacer"></span>
                  <span class="muted small">${t("detail_driver_values", {
                    share: percent(a.share, this.lang),
                    rate: percent(a.change_rate, this.lang),
                    bytes: bytes(a.bytes, this.lang),
                  })}</span></div>`
              )}
              <p class="muted small">${t("detail_drivers_hint")}</p>`
          : nothing}
        ${d.attributes.length
          ? html`<h4>${t("detail_attributes", { n: number(d.attribute_variants, this.lang) })}</h4>
              ${d.attributes.map(
                (a) => html`<div class="attr"><code>${a.name}</code><span class="spacer"></span><span class="muted small">${bytes(a.bytes, this.lang)}</span></div>`
              )}
              <p class="muted small">${t("detail_attributes_hint")}</p>`
          : nothing}

        <h4>${t("detail_usage")}</h4>
        <ul class="usage">
          ${autoNames.length ? html`<li>${t("detail_automations")}: ${autoNames.join(", ")}</li>` : nothing}
          ${scriptNames.length ? html`<li>${t("detail_scripts")}: ${scriptNames.join(", ")}</li>` : nothing}
          ${(usage.helpers || []).map((h) => html`<li>${t("detail_helper", { title: h.title, domain: h.domain })}
            ${["statistics", "history_stats", "filter"].includes(h.domain) ? html`<span class="tag ok">${t("protected_history_reader")}</span>` : nothing}</li>`)}
          ${(usage.dashboards || []).map((db) => html`<li>${t("detail_dashboard", { title: db.dashboard, card: db.card, days: db.days })}</li>`)}
          ${usage.energy ? html`<li>${t("note_energy")}</li>` : nothing}
          ${!autoNames.length && !scriptNames.length && !(usage.helpers || []).length && !(usage.dashboards || []).length && !usage.energy
            ? html`<li class="muted">${t("detail_unused")}</li>`
            : nothing}
        </ul>
        <p class="muted small">${t("detail_usage_limits")}</p>

        ${advice?.action
          ? html`<div class="banner ${advice.conflict ? "" : "info"}" style="margin:12px 0">
              <div class="txt"><b>${t("suggested", { tier: this._tierLabel(advice.action) })}</b><br />${this._reasonText(advice, row)}
                ${advice.saving ? html`<br /><span class="muted small">${t("detail_saving", { bytes: bytes(advice.saving, this.lang) })}</span>` : nothing}</div>
              <button class="btn primary" @click=${() => this._accept([d.entity_id])}>${t("inbox_accept")}</button>
            </div>`
          : nothing}

        <h4>${t("col_retention")}</h4>
        ${row ? this._tierSelect(row, (v) => this._setValue([row], v)) : nothing}
        <p class="small">${t(`impact_${value}`, { days: TIER_DAYS[value] ?? d.keep_days })}</p>
      `;
    }
  };
